from decimal import Decimal as D
records = {
    ("cust+mat", ("C100", "M-01")): D("9000"),
    ("pricelist+mat", ("P2", "M-01")): D("9500"),
    ("mat", ("M-01",)): D("10000"),
}
access_seq = [
    ("cust+mat", lambda o: (o["cust"], o["mat"])),
    ("pricelist+mat", lambda o: (o["plist"], o["mat"])),
    ("mat", lambda o: (o["mat"],)),
]
def price(order):
    for table, key in access_seq:
        hit = records.get((table, key(order)))
        if hit is not None:
            return table, hit
    return None, None

print(price({"cust": "C100", "plist": "P2", "mat": "M-01"}))  # ('cust+mat', Decimal('9000'))
print(price({"cust": "C200", "plist": "P2", "mat": "M-01"}))  # ('pricelist+mat', Decimal('9500'))
print(price({"cust": "C300", "plist": "P9", "mat": "M-01"}))  # ('mat', Decimal('10000'))
